import sys

def solve():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    n = len(s)
    m = len(t)

    if m > n:
        print("No")
        return

    left = [0] * m
    right = [0] * m

    idx = 0
    for i in range(n):
        if idx < m and s[i] == t[idx]:
            left[idx] = i
            idx += 1

    if idx != m:
        print("No")
        return

    idx = m - 1
    for i in range(n - 1, -1, -1):
        if idx >= 0 and s[i] == t[idx]:
            right[idx] = i
            idx -= 1

    covered = [False] * n
    current_left = 0
    current_right = m - 1

    for i in range(n):
        if current_left < m and left[current_left] == i:
            covered[i] = True
            current_left += 1
        elif current_right >= 0 and right[current_right] == i:
            covered[i] = True
            current_right -= 1

    if all(covered):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
